DECLARE
    V_REQUEST_ID RAW(16);
    V_JSON       CLOB;
BEGIN

    V_REQUEST_ID :=
        HEXTORAW(
            REPLACE(
                '{{ JS_ADD_TERMINAL.getRequestId() }}',
                '-',
                ''
            )
        );

    V_JSON :=
        '{{ JSON.stringify(
            JS_ADD_TERMINAL.getCreateRequestData()
        ) }}';

    TALY_BO_REP.MMS_ONBOARDING_PKG.UPDATE_ADD_TERMINAL_DRAFT(
        P_REQUEST_ID  => V_REQUEST_ID,
        P_REQUEST_JSON => V_JSON
    );

END;
